begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000005601','catalog-parent@test.local'),('00000000-0000-4000-8000-000000005602','catalog-editor@test.local'),('00000000-0000-4000-8000-000000005603','catalog-editor-two@test.local');
insert into public.admins(user_id) values('00000000-0000-4000-8000-000000005602'),('00000000-0000-4000-8000-000000005603');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000005601','Catalogue test','00000000-0000-4000-8000-000000005601');
insert into public.family_members(user_id,family_id) values('00000000-0000-4000-8000-000000005601','10000000-0000-4000-8000-000000005601');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000005601','10000000-0000-4000-8000-000000005601','Test child',5);
create function pg_temp.bundle() returns jsonb language sql as $$select '
{"schema": "gina.curriculum-review.v1", "candidates": [{"key": "tr-2026-2027-t1-turkce2-g5-c6", "academic_year": "2026-2027", "term": 1, "exam": 1, "grade": 5, "subject": "Türkçe", "source_url": "https://cdn.eba.gov.tr/yardimcikaynaklar/2026/09/KSDT/turkce2.xlsx", "source_sha256": "6405d02aaaadaa4d25a3ce54954dd256a045da9f35d49ee806a3b29565a82cee", "sheet": "5. Sınıf", "header_cell": "C6", "question_count": 6, "blocks": [{"count": 2, "count_cell": "C12", "outcomes": [{"cell": "B12", "text": "T.O.5.6. Metnin yüzey anlamını belirleyebilme", "code": "T.O.5.6"}]}, {"count": 1, "count_cell": "C13", "outcomes": [{"cell": "B13", "text": "T.O.5.7. Görselle iletilen anlamı belirleyebilme", "code": "T.O.5.7"}]}, {"count": 1, "count_cell": "C21", "outcomes": [{"cell": "B21", "text": "T.O.5.20. Metinden hareketle söz varlığını geliştirmeye yönelik çözümleme yapabilme", "code": "T.O.5.20"}]}, {"count": 1, "count_cell": "C30", "outcomes": [{"cell": "B30", "text": "T.Y.5.13. Yazısını zenginleştirecek biçimde söz varlığını kullanabilme", "code": "T.Y.5.13"}]}, {"count": 1, "count_cell": "C32", "outcomes": [{"cell": "B32", "text": "T.Y.5.16. Yazım ve noktalama işaretleriyle ilgili kuralları uygulayabilme", "code": "T.Y.5.16"}]}], "label": "Senaryo 1", "review_reasons": ["programme_and_school_scope_required", "source_review_required"]}]}
'::jsonb$$;
create function pg_temp.review() returns jsonb language sql as $$select '{"programme":"Test programme version","school_scope":"Synthetic scope for testing only","programme_url":"https://tymm.meb.gov.tr/ogretim-programlari","source_checked":true,"counts_checked":true,"applicability_checked":true,"issues_resolution":"Synthetic evidence reviewed for test only.","note":"Test source review, not real catalogue approval."}'::jsonb$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005601","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005601"}}',true);
select throws_ok($$select public.admin_import_curriculum_candidates(gen_random_uuid(),pg_temp.bundle())$$,'42501','forbidden','parent cannot import official candidates');
select throws_ok($$select public.admin_list_curriculum_candidates()$$,'42501','forbidden','review queue private');
select throws_ok($$select * from gina.curriculum_candidates$$,'42501',null,'no direct table access');
select is(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2026-2027',1,1,'Türkçe'),'[]'::jsonb,'feature starts closed');
select throws_ok($$select public.get_curriculum_scenarios(gen_random_uuid(),'2026-2027',1,1,'Türkçe')$$,'42501','forbidden','foreign child rejected even with feature closed');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005602","role":"authenticated","gina":{"role":"parent","admin":true}}',true);
select set_config('test.import',public.admin_import_curriculum_candidates('60000000-0000-4000-8000-000000005601',pg_temp.bundle())::text,true);
select is(current_setting('test.import')::jsonb->>'created','1','one source draft imported');
select is(public.admin_import_curriculum_candidates('60000000-0000-4000-8000-000000005601',pg_temp.bundle())::text,current_setting('test.import'),'exact import replay');
select is(public.admin_import_curriculum_candidates(gen_random_uuid(),pg_temp.bundle())->>'existing','1','same source content deduplicated');
select throws_ok($$select public.admin_import_curriculum_candidates('60000000-0000-4000-8000-000000005601',jsonb_set(pg_temp.bundle(),'{candidates,0,label}','"Different"'))$$,'P0001','request_conflict','same receipt different input rejected');
select throws_ok($$select public.admin_import_curriculum_candidates(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{candidates,0,label}','"Different"'))$$,'P0001','curriculum_source_changed','same source version cannot be silently overwritten');
select throws_ok($$select public.admin_import_curriculum_candidates(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{candidates,0,question_count}','30'))$$,'P0001','curriculum_count_mismatch','outcome blocks retain total');
select throws_ok($$select public.admin_import_curriculum_candidates(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{candidates,0,source_url}','"https://meb.gov.tr.evil.invalid/source"'))$$,'P0001','curriculum_source_invalid','official-looking foreign hostname rejected');
select throws_ok($$select public.admin_import_curriculum_candidates(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{candidates,0,grade}','1'))$$,'P0001',null,'primary practice not mislabelled common written exam');
select throws_ok($$select public.admin_import_curriculum_candidates(gen_random_uuid(),pg_temp.bundle()||jsonb_build_object('published',true))$$,'P0001',null,'cannot import approval');
select throws_ok($$select public.admin_import_curriculum_candidates(gen_random_uuid(),jsonb_set(pg_temp.bundle(),'{candidates}',(pg_temp.bundle()->'candidates')||(pg_temp.bundle()->'candidates')))$$,'P0001','curriculum_duplicate','duplicate entries fail whole transaction');
select set_config('test.id',public.admin_list_curriculum_candidates()->0->>'id',true);
select is(public.admin_get_curriculum_candidate(current_setting('test.id')::uuid)->>'status','draft','import never marks reviewed');
select is(public.admin_get_curriculum_candidate(current_setting('test.id')::uuid)->'candidate',pg_temp.bundle()->'candidates'->0,'all exact source cells and wording kept');
select throws_ok($$select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,0,'publish',null,'Publish',true)$$,'P0001','curriculum_review_required','unreviewed source cannot publish');
select throws_ok($$select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,0,'review',pg_temp.review()||'{"counts_checked":false}','Review',true)$$,'P0001','curriculum_review_required','all evidence checks required');
select throws_ok($$select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,0,'review',pg_temp.review(),'Review',false)$$,'P0001','curriculum_review_required','explicit review required');
select set_config('test.review',public.admin_change_curriculum_candidate('60000000-0000-4000-8000-000000005602',current_setting('test.id')::uuid,0,'review',pg_temp.review(),'Review',true)::text,true);
select is(current_setting('test.review')::jsonb->>'status','reviewed','review stays separate from publishing');
select is(public.admin_change_curriculum_candidate('60000000-0000-4000-8000-000000005602',current_setting('test.id')::uuid,0,'review',pg_temp.review(),'Review',true)::text,current_setting('test.review'),'lost review response exact replay');
select throws_ok($$select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,0,'review',pg_temp.review(),'Other review',true)$$,'P0001','curriculum_revision_conflict','stale review cannot overwrite');
select is(public.admin_change_curriculum_candidate('60000000-0000-4000-8000-000000005603',current_setting('test.id')::uuid,1,'publish',null,'Synthetic publication',true)->>'status','published','separate publication action');
select throws_ok($$select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,2,'review',pg_temp.review(),'Edit live',true)$$,'P0001','curriculum_withdraw_first','live source cannot change silently');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005601","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005601"}}',true);
select is(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2026-2027',1,1,'Türkçe'),'[]'::jsonb,'published still hidden behind feature flag');
reset role;update public.app_settings set value='true' where key='curriculum_catalog.enabled';set local role authenticated;
select is(jsonb_array_length(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2026-2027',1,1,'Türkçe')),1,'published scenario matches own child grade and requested scope');
select is(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2026-2027',1,2,'Türkçe'),'[]'::jsonb,'other exam not offered');
select is(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2025-2026',1,1,'Türkçe'),'[]'::jsonb,'other year not offered');
select is(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2026-2027',1,1,'Matematik'),'[]'::jsonb,'other subject not offered');
select ok((public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2026-2027',1,1,'Türkçe')->0) ? 'school_scope','applicability visible, not auto-selected');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005602","role":"authenticated","gina":{"role":"parent","admin":true}}',true);
select is(public.admin_change_curriculum_candidate('60000000-0000-4000-8000-000000005604',current_setting('test.id')::uuid,2,'withdraw',null,'Correction required',true)->>'status','withdrawn','withdraw stops new selection');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005603","role":"authenticated","gina":{"role":"parent","admin":true}}',true);
select throws_ok($$select public.admin_change_curriculum_candidate('60000000-0000-4000-8000-000000005604',current_setting('test.id')::uuid,2,'withdraw',null,'Correction required',true)$$,'P0001','request_conflict','receipt scoped to initiating operator');
select throws_ok($$select public.admin_change_curriculum_candidate(gen_random_uuid(),current_setting('test.id')::uuid,3,'publish',null,'Reopen',true)$$,'P0001','curriculum_review_required','withdrawn version requires a fresh review');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000005601","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005601"}}',true);
select is(public.get_curriculum_scenarios('20000000-0000-4000-8000-000000005601','2026-2027',1,1,'Türkçe'),'[]'::jsonb,'withdrawn no longer exposed');
reset role;
select is((select count(*)::int from public.exam_blueprints),0,'catalogue review never creates family scenario');
select is((select count(*)::int from public.question_bank),0,'catalogue publication never creates questions');
select * from finish();rollback;
